import 'package:flutter/material.dart';import '../../../core/network/football_repository.dart';
class DiscoveryScreen extends StatefulWidget{const DiscoveryScreen({super.key});@override State<DiscoveryScreen> createState()=>_DiscoveryScreenState();}
class _DiscoveryScreenState extends State<DiscoveryScreen>{final repo=FootballRepository(),ctrl=TextEditingController();Map<String,dynamic>?results;List<dynamic> trends=[];@override void initState(){super.initState();repo.trending().then((v){if(mounted)setState(()=>trends=v);});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Discover')),body:ListView(padding:const EdgeInsets.all(16),children:[SearchBar(controller:ctrl,hintText:'Teams, players, competitions, news',onChanged:(q)async{if(q.trim().isEmpty){setState(()=>results=null);return;}final r=await repo.suggestions(q);if(mounted)setState(()=>results=r);}),const SizedBox(height:18),if(results==null)...[Text('Trending',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w900)),Wrap(spacing:8,children:trends.map((t)=>ActionChip(label:Text('${t['query']}'),onPressed:(){ctrl.text='${t['query']}';})).toList())]else ...results!.entries.map((e)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e.key.toUpperCase(),style:const TextStyle(fontWeight:FontWeight.w900)),...List<dynamic>.from(e.value).map((x)=>ListTile(title:Text('${x['name_en']??x['name_ar']??x['name']??x['title']??''}')))]))))]));}
